class RawCDPPhoneUIAdapter:
    def __init__(self, runner: NodeCDPRunner):
        self.runner = runner

    def observe_eligibility(self, remote_channel_id: str) -> EligibilityObservation:
        self.remote_channel_id = remote_channel_id
        result = self.runner.run("VERIFY_OBSERVE", CHANNEL_ID=remote_channel_id)
        state = str(result.get("state") or "UNKNOWN")
        if state == "VERIFIED":
            return EligibilityObservation(False, True, "VERIFIED")
        if state == "PHONE_REQUIRED":
            return EligibilityObservation(True, False, "PHONE_REQUIRED")
        if state == "NEEDS_OPERATOR":
            return EligibilityObservation(True, False, "NEEDS_OPERATOR")
        return EligibilityObservation(True, False, "UNKNOWN")

    def submit_phone(self, phone_number: str) -> str:
        result = self.runner.run("VERIFY_SUBMIT_PHONE", PHONE_NUMBER=phone_number, CHANNEL_ID=getattr(self, "remote_channel_id", ""))
        return str(result.get("state") or "UNKNOWN")

    def reconcile_phone_submission(self) -> str:
        result = self.runner.run("VERIFY_RECONCILE_PHONE", CHANNEL_ID=getattr(self, "remote_channel_id", ""))
        return str(result.get("state") or "UNKNOWN")

    def submit_otp(self, code: str) -> str:
        result = self.runner.run("VERIFY_SUBMIT_OTP", OTP_CODE=code, CHANNEL_ID=getattr(self, "remote_channel_id", ""))
        return str(result.get("state") or "UNKNOWN")

    def reconcile_otp_submission(self) -> str:
        result = self.runner.run("VERIFY_RECONCILE_OTP", CHANNEL_ID=getattr(self, "remote_channel_id", ""))
        return str(result.get("state") or "UNKNOWN")


class RawCDPPublishAdapter:
    def __init__(self, runner: NodeCDPRunner):
        self.runner = runner

    def observe_private_upload(
        self,
        remote_channel_id: str,
        package: SealedContentPackage,
    ) -> PublishObservation:
        title = str(package.metadata.get("title") or "").strip()
        if not title:
            return PublishObservation("UNCERTAIN", evidence={"reason": "sealed title missing"})
        result = self.runner.run(
            "PUBLISH_OBSERVE",
            CHANNEL_ID=remote_channel_id,
            )

    def set_workspace_health(self, workspace_id: str, health: WorkspaceHealth | str) -> None:
        value = health.value if isinstance(health, WorkspaceHealth) else str(health)
        if value not in {item.value for item in WorkspaceHealth}:
            raise InvalidTransitionError(f"invalid Workspace health: {value}")
        now = _now()
        with self._transaction() as db:
            self._require_row(db, "workspaces", "workspace_id", workspace_id)
            db.execute(
                "UPDATE workspaces SET health=?, updated_at=? WHERE workspace_id=?",
                (value, now, workspace_id),
            )

    def get_active_operation(self, workspace_id: str) -> OperationRecord | None:
        with self._reader() as db:
            row = db.execute(
                """SELECT o.* FROM operations o
                JOIN workspace_active_operations a ON a.operation_id=o.operation_id
                WHERE a.workspace_id=?""",
                (workspace_id,),
            ).fetchone()
        return self._operation_from_row(row) if row else None

    def list_recovery_operations(self) -> list[OperationRecord]:
        with self._reader() as db:
            rows = db.execute(
                """SELECT DISTINCT o.* FROM operations o
                JOIN workspace_active_operations a ON a.operation_id=o.operation_id
                LEFT JOIN external_effects e ON e.operation_id=o.operation_id
                WHERE o.state IN ('RECONCILE_REQUIRED','NEEDS_OPERATOR','DISPATCHED','CONFIRMING')
                   OR e.state IN ('RECONCILE_REQUIRED','NEEDS_OPERATOR','DISPATCHED','CONFIRMING')
                ORDER BY o.created_at"""
            ).fetchall()
        return [self._operation_from_row(row) for row in rows]

    def can_delete_workspace(self, workspace_id: str) -> bool:
        with self._reader() as db:
            self._require_row(db, "workspaces", "workspace_id", workspace_id)
            active = db.execute(
                "SELECT 1 FROM workspace_active_operations WHERE workspace_id=?",
                (workspace_id,),
            ).fetchone()
            unresolved = db.execute(
                """SELECT 1 FROM external_effects
                WHERE workspace_id=? AND state NOT IN ('SUCCEEDED','FAILED_KNOWN','CANCELLED')
                LIMIT 1""",
                (workspace_id,),
            ).fetchone()
        return not active and not unresolved

    def delete_workspace_local(self, workspace_id: str) -> None:
        if not self.can_delete_workspace(workspace_id):
            raise UnsafeDeleteError("Workspace has active operation or unresolved external-effect evidence")
        now = _now()
        with self._transaction() as db:
            db.execute(
                """UPDATE workspaces
                SET archive_state='DELETED_LOCAL', health=?, current_operation_kind='IDLE', updated_at=?
                WHERE workspace_id=?""",
                (WorkspaceHealth.ARCHIVED.value, now, workspace_id),
            )

    def get_operation(self, operation_id: str) -> OperationRecord:
        with self._reader() as db:
            row = db.execute("SELECT * FROM operations WHERE operation_id=?", (operation_id,)).fetchone()
        if not row:
            raise NotFoundError(f"Operation not found: {operation_id}")
        return self._operation_from_row(row)

    def get_effect(self, effect_id: str) -> EffectRecord:
        with self._reader() as db:
            row = db.execute("SELECT * FROM external_effects WHERE effect_id=?", (effect_id,)).fetchone()
        if not row:
            raise NotFoundError(f"ExternalEffect not found: {effect_id}")
        return self._effect_from_row(row)

    def list_effects(self, operation_id: str) -> list[EffectRecord]:
        with self._reader() as db:
            rows = db.execute(
                "SELECT * FROM external_effects WHERE operation_id=? ORDER BY created_at",
                (operation_id,),
            ).fetchall()
        return [self._effect_from_row(row) for row in rows]

    def get_latest_effect_for_workspace(
        self,
        workspace_id: str,
        effect_type: str,
    ) -> EffectRecord | None:
        with self._reader() as db:
            row = db.execute(
                """SELECT * FROM external_effects
                WHERE workspace_id=? AND effect_type=?
                ORDER BY updated_at DESC, created_at DESC
                LIMIT 1""",
                (workspace_id, effect_type),
            ).fetchone()
        return self._effect_from_row(row) if row else None

    def find_succeeded_effect(
        self,
        workspace_id: str,
        effect_type: str,
        target_identity: str,
    ) -> EffectRecord | None:
        with self._reader() as db:
            row = db.execute(
                """SELECT * FROM external_effects
                WHERE workspace_id=? AND effect_type=? AND target_identity=? AND state='SUCCEEDED'
                ORDER BY updated_at DESC LIMIT 1""",
                (workspace_id, effect_type, target_identity),
            ).fetchone()
        return self._effect_from_row(row) if row else None

